#!/usr/bin/env python3
"""Writes formats/src/entities.rs from Python's html.entities.html5 and the
invalid-reference tables in html/__init__.py, so the Rust from_html decodes
entities exactly as Python's html.unescape does."""
import html
import html.entities as he


def lit(s):
    return '"' + ''.join(c if (c.isalnum() or c in ';') else '\\u{%x}' % ord(c) for c in s) + '"'


out = ["//! The HTML5 named character references, as Python's html.entities.html5 has them.",
       '//! Generated by tools/gen_entities.py; do not edit.', '',
       '/// (name, value); names that may appear without a semicolon are listed without one too.',
       'pub static ENTITIES: &[(&str, &str)] = &[']
out += [f'    ({lit(k)}, {lit(v)}),' for k, v in sorted(he.html5.items())]
out += ['];', '', '/// Numeric references html.unescape maps to something else.',
        'pub static INVALID_CHARREFS: &[(u32, &str)] = &[']
out += [f'    (0x{k:x}, {lit(v)}),' for k, v in sorted(html._invalid_charrefs.items())]
out += ['];', '', '/// Code points html.unescape drops from numeric references.', 'pub static INVALID_CODEPOINTS: &[u32] = &[']
cps = sorted(html._invalid_codepoints)
out += ['    ' + ', '.join(f'0x{c:x}' for c in cps[i:i + 12]) + ',' for i in range(0, len(cps), 12)]
out.append('];')
with open('formats/src/entities.rs', 'w') as f:
    f.write('\n'.join(out) + '\n')
